mapper.select:
SELECT , 1 AS is_favorite FROM biz_question q LEFT JOIN biz_text_content tc_s ON tc_s.question_id = q.id AND tc_s.content_type = 'S' INNER JOIN biz_question_favorite f ON f.question_id = q.id AND f.user_id = #{currentUserId} WHERE q.status <> '2'
AND f.folder_id = #{folderId}
ORDER BY f.create_time DESC, q.id DESC

SELECT q.id, q.question_type, q.difficult, q.subject_id,
CASE WHEN q.import_source = 'misikt' THEN NULL ELSE COALESCE(tc_s.content, q.stem_text) END AS stem_text_resolved, tc_a.content AS answer_resolved, tc_e.content AS explain_resolved, q.stem_text, q.stem_img_url, q.answer_img_url, q.explain_img_url, q.file_bin_url, 0 AS score_val, q.exam_year, q.exam_paper_id, q.exam_paper_name, q.status, q.create_user, q.create_by, UNIX_TIMESTAMP(q.create_time) * 1000 AS create_time_ms, UNIX_TIMESTAMP(q.update_time) * 1000 AS update_time_ms, q.update_by,
(SELECT bt.content FROM biz_text_content bt WHERE bt.id = q.stem_text_content_id) AS stem_text_content, (SELECT bt.content FROM biz_text_content bt WHERE bt.id = q.answer_text_content_id) AS answer_text_content, (SELECT bt.content FROM biz_text_content bt WHERE bt.id = q.analyze_text_content_id) AS analyze_text_content, q.label_status AS label_status FROM biz_question q LEFT JOIN biz_text_content tc_s ON tc_s.question_id = q.id AND tc_s.content_type = 'S' LEFT JOIN biz_text_content tc_a ON tc_a.question_id = q.id AND tc_a.content_type = 'A' LEFT JOIN biz_text_content tc_e ON tc_e.question_id = q.id AND tc_e.content_type = 'E' WHERE q.id = #{id}
